package main

import "testing"

func TestParseLsof(t *testing.T) {
	got, err := parseLsof([]byte("p10\ncnode\nn*:3000\n"))
	if err != nil || len(got) != 1 || got[0].Port != 3000 {
		t.Fatalf("got %v, %v", got, err)
	}
}

